CREATE SCHEMA "app";
CREATE TYPE "app"."post_status" AS ENUM ('draft', 'published', 'archived');
CREATE DOMAIN "app"."email_address" AS text CONSTRAINT "email_address_check" CHECK (char_length(VALUE) <= 320);
CREATE DOMAIN "app"."slug_text" AS text CONSTRAINT "slug_text_check" CHECK (VALUE ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
CREATE TYPE "app"."money_amount" AS ("amount" numeric(12,2), "currency" character(3));
CREATE TABLE "app"."post_tags" (
  "post_id" bigint NOT NULL,
  "tag_id" bigint NOT NULL,
  CONSTRAINT "post_tags_pkey" PRIMARY KEY ("post_id", "tag_id")
);
CREATE TABLE "app"."posts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "app"."posts_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807) NOT NULL,
  "author_id" bigint NOT NULL,
  "editor_id" bigint,
  "title" text NOT NULL,
  "slug" text GENERATED ALWAYS AS (lower(replace(title, ' '::text, '-'::text))) STORED,
  "status" app.post_status DEFAULT 'draft'::app.post_status NOT NULL,
  "price" app.money_amount,
  "labels" text[],
  "published_at" timestamp with time zone,
  CONSTRAINT "posts_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "posts_published_check" CHECK (((published_at IS NULL) OR (status <> 'draft'::app.post_status))),
  CONSTRAINT "posts_title_check" CHECK (char_length("title") BETWEEN 1 AND 200)
);
CREATE TABLE "app"."profiles" (
  "user_id" bigint NOT NULL,
  "bio" text,
  "birthday" date,
  CONSTRAINT "profiles_pkey" PRIMARY KEY ("user_id")
);
CREATE TABLE "app"."tags" (
  "id" bigint GENERATED ALWAYS AS IDENTITY (SEQUENCE NAME "app"."tags_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807) NOT NULL,
  "name" app.slug_text NOT NULL,
  CONSTRAINT "tags_name_key" UNIQUE ("name"),
  CONSTRAINT "tags_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "app"."tenants" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "name" text NOT NULL,
  CONSTRAINT "tenants_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "app"."users" (
  "id" bigint GENERATED ALWAYS AS IDENTITY (SEQUENCE NAME "app"."users_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807) NOT NULL,
  "tenant_id" uuid NOT NULL,
  "email" app.email_address NOT NULL,
  "display_name" character varying(80),
  "password_hash" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "version" integer DEFAULT 1 NOT NULL,
  CONSTRAINT "users_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "users_tenant_email_key" UNIQUE ("tenant_id", "email")
);
CREATE FUNCTION "app"."post_score"("p_id" bigint) RETURNS numeric LANGUAGE sql STABLE STRICT PARALLEL UNSAFE AS $dql$ SELECT 0::numeric $dql$;
CREATE FUNCTION "app"."post_score"("p_id" bigint, "window_days" integer) RETURNS numeric LANGUAGE sql STABLE STRICT PARALLEL UNSAFE AS $dql$ SELECT 0::numeric $dql$;
ALTER TABLE "app"."post_tags" ADD CONSTRAINT "post_tags_post_id_fkey" FOREIGN KEY ("post_id") REFERENCES "app"."posts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "app"."post_tags" ADD CONSTRAINT "post_tags_tag_id_fkey" FOREIGN KEY ("tag_id") REFERENCES "app"."tags" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
CREATE UNIQUE INDEX posts_one_published_slug ON app.posts USING btree (slug) WHERE (status = 'published'::app.post_status);
ALTER TABLE "app"."posts" ADD CONSTRAINT "posts_author_id_fkey" FOREIGN KEY ("author_id") REFERENCES "app"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "app"."posts" ADD CONSTRAINT "posts_editor_id_fkey" FOREIGN KEY ("editor_id") REFERENCES "app"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "app"."profiles" ADD CONSTRAINT "profiles_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "app"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "app"."users" ADD CONSTRAINT "users_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "app"."tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
CREATE VIEW "app"."published_posts" AS SELECT id,
    title,
    author_id,
    published_at
   FROM app.posts
  WHERE (status = 'published'::app.post_status);
ALTER SCHEMA "app" OWNER TO "dql_fixture_owner";
ALTER TYPE "app"."post_status" OWNER TO "dql_fixture_owner";
ALTER DOMAIN "app"."email_address" OWNER TO "dql_fixture_owner";
ALTER DOMAIN "app"."slug_text" OWNER TO "dql_fixture_owner";
ALTER TYPE "app"."money_amount" OWNER TO "dql_fixture_owner";
ALTER TABLE "app"."post_tags" OWNER TO "dql_fixture_owner";
ALTER TABLE "app"."posts" OWNER TO "dql_fixture_owner";
COMMENT ON CONSTRAINT "profiles_user_id_fkey" ON "app"."profiles" IS '@inverse-name(user_profile)';
ALTER TABLE "app"."profiles" OWNER TO "dql_fixture_owner";
COMMENT ON VIEW "app"."published_posts" IS '@logical-key(id)';
ALTER VIEW "app"."published_posts" OWNER TO "dql_fixture_owner";
COMMENT ON COLUMN "app"."published_posts"."id" IS '@nonnull';
COMMENT ON COLUMN "app"."published_posts"."title" IS '@nonnull';
ALTER TABLE "app"."tags" OWNER TO "dql_fixture_owner";
ALTER TABLE "app"."tenants" OWNER TO "dql_fixture_owner";
COMMENT ON COLUMN "app"."users"."tenant_id" IS '@bound';
COMMENT ON COLUMN "app"."users"."password_hash" IS '@write-only @sensitive';
COMMENT ON COLUMN "app"."users"."created_at" IS '@immutable';
COMMENT ON COLUMN "app"."users"."updated_at" IS '@db-updated';
COMMENT ON COLUMN "app"."users"."version" IS '@version';
ALTER TABLE "app"."users" OWNER TO "dql_fixture_owner";
COMMENT ON FUNCTION "app"."post_score"(bigint) IS '@public';
ALTER FUNCTION "app"."post_score"(bigint) OWNER TO "dql_fixture_owner";
COMMENT ON FUNCTION "app"."post_score"(bigint, integer) IS '@public';
ALTER FUNCTION "app"."post_score"(bigint, integer) OWNER TO "dql_fixture_owner";
